/**
 * POST /marketing/email-preferences - Update marketing email consent
 *
 * Two supported modes:
 *
 * 1) Authenticated (account-page toggle):
 *    - User must be logged in.
 *    - settings.action = 'opt-in' | 'opt-out'.
 *    - Writes canonical consent.marketing to user doc.
 *    - Hits BOTH SendGrid + Beehiiv via the email library (one source of truth).
 *
 * 2) Anonymous (HMAC unsubscribe link from email footer):
 *    - No login. settings.email + settings.asmId + settings.sig + settings.action.
 *    - HMAC validates the link was generated by us.
 *    - Hits SendGrid ASM directly (legacy behavior — preserves existing one-click unsub).
 *    - Also writes canonical consent.marketing to user doc when email maps to a user.
 *    - Then cross-syncs via the email library (best-effort): unsubscribe removes the
 *      contact from ALL providers (Beehiiv too — compliance); subscribe re-adds the
 *      contact (sync when the email maps to a user, add when it doesn't).
 */
import fetch from 'wonderful-fetch';
import crypto from 'crypto';
import env from '../../../libraries/env.js';
import rateLimits from '../../../libraries/rate-limits.js';

const { MARKETING_RATE_LIMIT } = rateLimits;

export default async ({ ctx, omega, user, data, analytics }) => {

  // --- AUTHENTICATED MODE ---
  if (user.authenticated) {
    return handleAuthenticated({ ctx, omega, user, data, analytics });
  }

  // --- ANONYMOUS HMAC MODE ---
  return handleAnonymous({ ctx, omega, data, analytics });
};

/**
 * Authenticated user toggling marketing on/off from the account page.
 */
async function handleAuthenticated({ ctx, omega, user, data, analytics }) {
  const admin = omega.firebase.admin;
  const action = data.action;

  if (action !== 'subscribe' && action !== 'unsubscribe') {
    return ctx.respond('Invalid action — must be "subscribe" or "unsubscribe"', { code: 400 });
  }

  // Rate-limit per-user (defense against accidental toggling spam). consume()
  // is check, count and write in ONE call and throws the 429 itself
  // ([#647](https://github.com/Omega-JS-Stack/omega/issues/647)); the limit is
  // EXPLICIT because this is a framework anti-abuse gate, not a plan feature.
  try {
    await ctx.usage.consume('email-preferences', 1, { limit: MARKETING_RATE_LIMIT });
  } catch (e) {
    // Only a rate limit is a rate limit — a 500 from consume() must not come
    // back as one
    if (e.code !== 429) {
      throw e;
    }

    return ctx.respond('Rate limit exceeded', { code: 429 });
  }

  const uid = user.auth.uid;
  const email = user.auth.email;
  const ip = ctx.request.geolocation?.ip || null;
  const timestamp = ctx.meta.startTime.timestamp;
  const timestampUNIX = ctx.meta.startTime.timestampUNIX;

  // Build the consent.marketing mutation
  const marketingPatch = action === 'subscribe'
    ? {
      status: 'granted',
      grantedAt: { timestamp, timestampUNIX, source: 'account', ip, text: null },
      // Leave revokedAt untouched — informational record of most recent revoke
    }
    : {
      status: 'revoked',
      revokedAt: { timestamp, timestampUNIX, source: 'account', ip, text: null },
      // Leave grantedAt untouched — informational record of original grant
    };

  await admin.firestore().doc(`users/${uid}`).set({
    consent: { marketing: marketingPatch },
    metadata: ctx.metadata({ tag: 'marketing/email-preferences' }),
  }, { merge: true });

  ctx.log(`email-preferences (auth): ${uid} → ${action}`);

  // Skip provider calls in test mode unless extended mode is on
  const shouldCallExternalAPIs = !ctx.isTesting() || process.env.TEST_EXTENDED_MODE;

  if (shouldCallExternalAPIs) {
    const mailer = ctx.email;

    try {
      if (action === 'unsubscribe') {
        await mailer.remove(email);
      } else {
        await mailer.sync(uid);
      }
    } catch (e) {
      ctx.error(`email-preferences (auth) provider sync failed:`, e);
      // Doc is already updated — provider sync is best-effort. Don't fail the request.
    }
  } else {
    ctx.log('email-preferences (auth): Skipping provider calls (OMEGA_ENVIRONMENT=testing)');
  }

  analytics.event('marketing/email-preferences', { action, mode: 'authenticated' });

  return ctx.respond({ success: true, action });
}

/**
 * Anonymous HMAC unsubscribe link (preserves existing email-footer one-click flow).
 */
async function handleAnonymous({ ctx, omega, data, analytics }) {
  const admin = omega.firebase.admin;

  const email = (data.email || '').trim().toLowerCase();
  const asmId = parseInt(data.asmId, 10);
  const action = data.action || 'unsubscribe';

  // Validate inputs
  if (!email) {
    return ctx.respond('Email is required', { code: 400 });
  }

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    return ctx.respond('Invalid email format', { code: 400 });
  }

  if (!asmId || isNaN(asmId)) {
    return ctx.respond('ASM group ID is required', { code: 400 });
  }

  if (action !== 'subscribe' && action !== 'unsubscribe') {
    return ctx.respond('Invalid action', { code: 400 });
  }

  // HMAC validation (proves we generated this link)
  const expectedSig = crypto.createHmac('sha256', env.require('UNSUBSCRIBE_HMAC_KEY')).update(email).digest('hex');
  if (data.sig !== expectedSig) {
    return ctx.respond('Invalid signature', { code: 403 });
  }

  // IP rate limiting (anonymous flow) — an EXPLICIT keyed counter, which is
  // the only way an anonymous caller is counted now
  // ([#647](https://github.com/Omega-JS-Stack/omega/issues/647))
  try {
    await ctx.usage.forKey(ctx.request.geolocation.ip).consume('email-preferences', 1, { limit: MARKETING_RATE_LIMIT });
  } catch (e) {
    // Only a rate limit is a rate limit — a 500 from consume() must not come
    // back as one
    if (e.code !== 429) {
      throw e;
    }

    return ctx.respond('Rate limit exceeded', { code: 429 });
  }

  // Mirror to the user doc if this email maps to a user (best-effort, silent on miss).
  // Runs BEFORE the provider calls below — on subscribe it writes consent granted first,
  // so the email library's consent gate passes when we re-sync.
  const uid = await mirrorAnonymousToUserDoc({ ctx, omega, email, action });

  // Call SendGrid ASM (legacy behavior)
  const shouldCallExternalAPIs = !ctx.isTesting() || process.env.TEST_EXTENDED_MODE;

  if (!shouldCallExternalAPIs) {
    ctx.log('email-preferences (anon): Skipping SendGrid (OMEGA_ENVIRONMENT=testing)');
    return ctx.respond({ success: true });
  }

  try {
    if (action === 'unsubscribe') {
      // POST returns JSON ({recipient_emails: [...]}) on success
      await fetch(`https://api.sendgrid.com/v3/asm/groups/${asmId}/suppressions`, {
        method: 'POST',
        response: 'json',
        headers: { 'Authorization': `Bearer ${env.get('SENDGRID_API_KEY')}` },
        timeout: 60000,
        body: { recipient_emails: [email] },
      });
    } else {
      // DELETE returns 204 with empty body — must NOT request response: 'json'
      // or wonderful-fetch throws SyntaxError on the empty body.
      await fetch(`https://api.sendgrid.com/v3/asm/groups/${asmId}/suppressions/${encodeURIComponent(email)}`, {
        method: 'DELETE',
        response: 'text',
        headers: { 'Authorization': `Bearer ${env.get('SENDGRID_API_KEY')}` },
        timeout: 60000,
      });
    }
  } catch (e) {
    ctx.log(`SendGrid ASM ${action} error:`, e);
    return ctx.respond('Failed to process your request', { code: 500 });
  }

  // Cross-provider sync via the email library (best-effort — ASM suppression above
  // already succeeded). Unsubscribe must remove the contact from Beehiiv too
  // (compliance); subscribe must actually re-add the contact: sync the matched user
  // (the mirror above already wrote consent granted, so the library consent gate
  // passes) or add a bare newsletter contact when no user matched.
  const mailer = ctx.email;

  try {
    if (action === 'unsubscribe') {
      await mailer.remove(email);
    } else if (uid) {
      await mailer.sync(uid);
    } else {
      await mailer.add({ email, source: 'resubscribe' });
    }
  } catch (e) {
    ctx.error(`email-preferences (anon) provider sync failed:`, e);
    // Doc + ASM are already updated — provider sync is best-effort. Don't fail the request.
  }

  ctx.log('email-preferences (anon) result:', { email, asmId, action });
  analytics.event('marketing/email-preferences', { action, mode: 'anonymous' });

  return ctx.respond({ success: true });
}

/**
 * Anonymous HMAC unsub also writes to the user doc (if found) so consent stays in sync.
 * Silent if the email doesn't map to a user. Source is recorded as 'sendgrid' since the
 * HMAC link only fires from SendGrid email footers.
 *
 * @returns {Promise<string|null>} The matched user's uid, or null when no user matches.
 */
async function mirrorAnonymousToUserDoc({ ctx, omega, email, action }) {
  const admin = omega.firebase.admin;

  const snapshot = await admin.firestore().collection('users')
    .where('auth.email', '==', email)
    .limit(1)
    .get()
    .catch((e) => {
      ctx.error('email-preferences (anon): Failed to look up user by email:', e);
      return null;
    });

  if (!snapshot || snapshot.empty) {
    return null; // Silent — email may not map to a current user
  }

  const userDoc = snapshot.docs[0];
  const uid = userDoc.id;
  const timestamp = ctx.meta.startTime.timestamp;
  const timestampUNIX = ctx.meta.startTime.timestampUNIX;

  const marketingPatch = action === 'unsubscribe'
    ? {
      status: 'revoked',
      revokedAt: { timestamp, timestampUNIX, source: 'sendgrid', ip: null, text: null },
    }
    : {
      status: 'granted',
      grantedAt: { timestamp, timestampUNIX, source: 'sendgrid', ip: null, text: null },
    };

  await admin.firestore().doc(`users/${uid}`).set({
    consent: { marketing: marketingPatch },
    metadata: ctx.metadata({ tag: 'marketing/email-preferences' }),
  }, { merge: true })
    .catch((e) => {
      ctx.error(`email-preferences (anon): Failed to mirror to user doc ${uid}:`, e);
    });

  return uid;
}
